# ***** IR3 Instruction Representation & Decode *****

_OPS = {op: (val, lay) for bucket in DECODE_TABLE for _, val, lay, op in bucket}

class IR3Inst:
  def __init__(self, _raw:int|None = None, *, _op:str = "", _match:int = 0, _layout:int = 0, **kwargs:Any):
    self.op_name, self._layout = _op, _layout
    if _raw is not None:
      self._raw = _raw
      return
    raw, flds = _match, LAYOUTS[_layout]
    for k, v in kwargs.items():
      if k not in flds: raise TypeError(f"{_op}: unknown field {k!r}")
      lo, hi, signed, _ = flds[k]
      iv, mask = v.value if isinstance(v, FastEnum) else int(v), (1 << (hi - lo + 1)) - 1
      if signed:
        if not (-(1 << (hi - lo)) <= iv < (1 << (hi - lo))): raise ValueError(f"{_op}.{k}: {v} out of signed {hi - lo + 1}-bit range")
        iv &= mask
      elif not (0 <= iv <= mask): raise ValueError(f"{_op}.{k}: {v} does not fit in {hi - lo + 1} bits")
      raw = (raw & ~(mask << lo)) | (iv << lo)
    self._raw = raw
  @property
  def cat(self) -> int: return (self._raw >> 61) & 7
  @property
  def _fields(self) -> dict[str, tuple[int, int, bool, type[FastEnum]|None]]: return LAYOUTS[self._layout]
  def to_bytes(self) -> bytes: return self._raw.to_bytes(8, "little")
  def __hash__(self) -> int: return hash((self.op_name, self._raw))
  def __eq__(self, o:object) -> bool: return isinstance(o, IR3Inst) and self._raw == o._raw and self.op_name == o.op_name
  def __repr__(self) -> str: return f"{self.op_name}({self._raw:#018x})"
  def __reduce__(self): return decode_inst, (self._raw,)
  def __getattr__(self, name:str) -> Any:
    if (f := LAYOUTS[self._layout].get(name)) is None: raise AttributeError(f"{self.op_name!r} has no field {name!r}")
    lo, hi, signed, enum = f
    v = (self._raw >> lo) & ((1 << (hi - lo + 1)) - 1)
    if signed and (v & (1 << (hi - lo))): v -= 1 << (hi - lo + 1)
    return enum(v) if enum is not None else v

def ir3(op:str, **kwargs:Any) -> IR3Inst: return IR3Inst(_op=op, _match=_OPS[op][0], _layout=_OPS[op][1], **kwargs)

def decode_inst(word_or_bytes:int|bytes|memoryview) -> IR3Inst:
  word = int.from_bytes(word_or_bytes[:8], "little") if isinstance(word_or_bytes, (bytes, memoryview)) else int(word_or_bytes)
  for mask, val, lay, op_name in DECODE_TABLE[(word >> 61) & 7]:
    if (word & mask) == val: return IR3Inst(word, _op=op_name, _layout=lay)
  raise ValueError(f"ir3: cannot decode {word:#018x}")

def decode_insts(raw_code:bytes) -> list[IR3Inst]:
  return [decode_inst(raw_code[off:off + 8]) for off in range(0, len(raw_code) & ~7, 8)]

# ***** IR3 Semantic Models (cat1-cat4) *****

MEM_GLOBAL, MEM_LOCAL, MEM_PRIVATE = 0, 1, 2
_LD_SPACE, _ST_SPACE = {"ldg": MEM_GLOBAL, "ldl": MEM_LOCAL, "ldp": MEM_PRIVATE}, {"stg": MEM_GLOBAL, "stl": MEM_LOCAL, "stp": MEM_PRIVATE}
_BRANCH_OPS, _PRED_OPS = frozenset({"br", "brao", "braa", "bany", "ball", "brac", "brax"}), frozenset({"predt", "predf", "prede"})
_CFG_END_OPS = frozenset({"end", "jump", "bar"}) | _PRED_OPS | _BRANCH_OPS
_CAT2_UNARY = frozenset({"sign.f", "absneg.f", "floor.f", "ceil.f", "rndne.f", "rndaz.f", "trunc.f",
                         "absneg.s", "not.b", "bfrev.b", "clz.s", "clz.b", "cbits.b"})
_CAT3_ALT = frozenset({"shrm", "shlm", "shrg", "shlg", "andg"})

def _c(v:int, dt:DType = dtypes.int) -> UOp: return UOp.const(v, dt)
def _u(v:int, dt:DType = dtypes.uint32) -> UOp: return UOp.const(v, dt)
def _u64(v:int) -> UOp: return UOp.const(v, dtypes.uint64)
def _sext(v:int, bits:int) -> int: return (v & ((1 << (bits - 1)) - 1)) - (v & (1 << (bits - 1)))
def _f32_to_h16(x:UOp) -> UOp: return x.bitcast(dtypes.float32).cast(dtypes.half).bitcast(dtypes.uint16).cast(dtypes.uint32)
def _h16_to_f32(x:UOp) -> UOp: return x.cast(dtypes.uint16).bitcast(dtypes.half).cast(dtypes.float32).bitcast(dtypes.uint32)

def _bits_as(x:UOp, dt:DType) -> UOp:
  if dt == dtypes.half: return x.cast(dtypes.uint16).bitcast(dtypes.half)
  return x.cast(dtypes.uint32).bitcast(dtypes.float32) if dt == dtypes.float32 else x.cast(dt)

def _as_bits(x:UOp, is_half:bool) -> UOp:
  ut = dtypes.uint16 if is_half else dtypes.uint32
  if x.dtype == dtypes.half: return x.bitcast(dtypes.uint16).cast(ut)
  return x.bitcast(dtypes.uint32).cast(ut) if x.dtype == dtypes.float32 else x.cast(ut)

def _fmod(x:UOp, is_half:bool, neg:bool, ab:bool) -> UOp:
  if not neg and not ab: return x
  ut, sign, mask = (dtypes.uint16, 0x8000, 0x7fff) if is_half else (dtypes.uint32, 0x80000000, 0x7fffffff)
  b = (x.cast(ut) & _u(mask, ut)) if ab else x.cast(ut)
  return (b ^ _u(sign, ut)) if neg else b

def _sat(r:UOp, sat:bool) -> UOp:
  if not sat or not dtypes.is_float(r.dtype): return r
  z, o = UOp.const(0.0, r.dtype), UOp.const(1.0, r.dtype)
  return r.ne(r).where(z, (r > o).where(o, (r < z).where(z, r)))

_CMP = {
  IR3Cond.LT: lambda a, b: a < b, IR3Cond.GT: lambda a, b: b < a, IR3Cond.EQ: lambda a, b: a.eq(b), IR3Cond.NE: lambda a, b: a.ne(b),
  IR3Cond.LE: lambda a, b: ((a < b) | a.eq(b)) if dtypes.is_float(a.dtype) else (b < a).logical_not(),
  IR3Cond.GE: lambda a, b: ((b < a) | a.eq(b)) if dtypes.is_float(a.dtype) else (a < b).logical_not(),
}
_CAT4_FN = {
  "rcp": lambda a: a.alu(Ops.RECIP), "rsq": lambda a: a.sqrt().alu(Ops.RECIP), "hrsq": lambda a: a.sqrt().alu(Ops.RECIP),
  "log2": lambda a: a.log2(), "hlog2": lambda a: a.log2(), "exp2": lambda a: a.exp2(), "hexp2": lambda a: a.exp2(),
  "sin": lambda a: a.sin(), "sqrt": lambda a: a.sqrt(),
  "cos": lambda a: (a.cast(dtypes.float64) + UOp.const(math.pi / 2.0, dtypes.float64)).sin().cast(dtypes.float32),
}

def _sext24(x:UOp) -> UOp: return ((x.cast(dtypes.uint32) << _u(8)).cast(dtypes.int32)) >> _u(8, dtypes.int32)

def _eval_mov(st:IR3Type, dt:IR3Type, s0:UOp) -> UOp:
  if st is dt: return s0.cast(dtypes.uint16 if dt.is_half else dtypes.uint32)
  # Adreno ir3 has no TYPE_S8 in cat1 cov (Mesa emits cov.u8s16/cov.u8s32 for i8->i16/i32).
  return _as_bits(_bits_as(s0, dtypes.int8 if (st is IR3Type.U8 and dt in (IR3Type.S16, IR3Type.S32)) else st.dtype).cast(dt.dtype), dt.is_half)

def _clz(x:UOp, bits:int) -> UOp:
  ut = dtypes.uint16 if bits == 16 else dtypes.uint32
  v, cnt, step = x.cast(ut), _u(0, ut), bits // 2
  while step >= 1:
    hi = v >> _u(step, ut)
    z = hi.eq(_u(0, ut))
    cnt, v, step = z.where(cnt + _u(step, ut), cnt), z.where(v, hi), step // 2
  return x.cast(ut).eq(_u(0, ut)).where(_u((1 << bits) - 1, ut), cnt)

def _bitop_tree(x:UOp, bits:int, rev:bool) -> UOp:
  ut, full_m = dtypes.uint16 if bits == 16 else dtypes.uint32, (1 << bits) - 1
  v = x.cast(ut)
  for sh, m in ((1, 0x55555555), (2, 0x33333333), (4, 0x0f0f0f0f), (8, 0x00ff00ff), (16, 0x0000ffff)):
    if sh >= bits: break
    ml = _u(m & full_m, ut)
    v = (((v & ml) << _u(sh, ut)) | ((v & _u((~m) & full_m, ut)) >> _u(sh, ut))) if rev else ((v & ml) + ((v >> _u(sh, ut)) & ml))
  return v

def _rndne(a:UOp) -> UOp:
  af = a.cast(dtypes.float32) if a.dtype == dtypes.half else a
  z, h, o, two = (UOp.const(v, dtypes.float32) for v in (0.0, 0.5, 1.0, 2.0))
  t, neg = af.trunc(), af < z
  frac, step, odd = neg.where(t - af, af - t), neg.where(-o, o), ((t * h).trunc() * two).ne(t)
  return (frac > h).where(t + step, (frac.eq(h) & odd).where(t + step, t))

def _eval_cat2(op:str, full:bool, dst_h:bool, m0:tuple[bool, bool], m1:tuple[bool, bool], cond:IR3Cond, sat:bool, s0:UOp, s1:UOp) -> UOp:
  is_h, (s0n, s0a), (s1n, s1a) = not full, m0, m1
  if op.endswith(".f"):
    ft = dtypes.half if is_h else dtypes.float32
    a, z, h, o = _bits_as(_fmod(s0, is_h, s0n, s0a), ft), UOp.const(0.0, ft), UOp.const(0.5, ft), UOp.const(1.0, ft)
    uops = {"absneg.f": lambda: a, "trunc.f": a.trunc, "floor.f": lambda: (a < (t := a.trunc())).where(t - o, t),
            "ceil.f": lambda: ((t := a.trunc()) < a).where(t + o, t), "rndaz.f": lambda: (a < z).where((a - h).trunc(), (a + h).trunc()),
            "rndne.f": lambda: _rndne(a), "sign.f": lambda: (a > z).where(o, (a < z).where(-o, z))}
    if op in uops: r = uops[op]()
    else:
      b = _bits_as(_fmod(s1, is_h, s1n, s1a), ft)
      if op == "cmps.f": return _as_bits(_CMP[cond](a, b), dst_h)
      if is_h and not dst_h: a, b = a.cast(dtypes.float32), b.cast(dtypes.float32)
      bops = {"add.f": lambda: a + b, "mul.f": lambda: a * b,
              "max.f": lambda: a.ne(a).where(b, b.ne(b).where(a, a.maximum(b))),
              "min.f": lambda: a.ne(a).where(b, b.ne(b).where(a, (a < b).where(a, b)))}
      if op not in bops: raise NotImplementedError(f"ir3: no UOp model for cat2 {op}")
      r = bops[op]()
    return _as_bits(_sat(r.cast(dtypes.half if dst_h else dtypes.float32) if (r.dtype == dtypes.half) != dst_h else r, sat), dst_h)

  bits, (ut, st) = (16, (dtypes.uint16, dtypes.int16)) if is_h else (32, (dtypes.uint32, dtypes.int32))
  au, bu, as_, bs_ = s0.cast(ut), s1.cast(ut), s0.cast(st), s1.cast(st)
  if op.endswith(".s") and op != "clz.s":
    z = _u(0, st)
    if s0a: as_ = (as_ < z).where(z - as_, as_)
    if s0n: as_ = z - as_
    if s1a: bs_ = (bs_ < z).where(z - bs_, bs_)
    if s1n: bs_ = z - bs_
  mask_all, sh = _u((1 << bits) - 1, ut), bu & _u(bits - 1, ut)
  if op in ("and.b", "or.b", "not.b", "xor.b"):
    if s0n: au = au ^ mask_all
    if s1n: bu = bu ^ mask_all
  iops = {
    "add.u": lambda: au + bu, "add.s": lambda: as_ + bs_, "sub.u": lambda: au - bu, "sub.s": lambda: as_ - bs_,
    "cmps.u": lambda: _CMP[cond](au, bu), "cmps.s": lambda: _CMP[cond](as_, bs_),
    "min.u": lambda: (au < bu).where(au, bu), "min.s": lambda: (as_ < bs_).where(as_, bs_),
    "max.u": lambda: au.maximum(bu), "max.s": lambda: as_.maximum(bs_), "absneg.s": lambda: as_,
    "and.b": lambda: au & bu, "or.b": lambda: au | bu, "not.b": lambda: au ^ mask_all, "xor.b": lambda: au ^ bu,
    "shl.b": lambda: au << sh, "shr.b": lambda: au >> sh, "ashr.b": lambda: as_ >> sh.cast(st),
    "mul.u24": lambda: (au.cast(dtypes.uint32) & _u(0xffffff)) * (bu.cast(dtypes.uint32) & _u(0xffffff)),
    "mul.s24": lambda: ((as_.cast(dtypes.int32) if is_h else _sext24(au)) * (bs_.cast(dtypes.int32) if is_h else _sext24(bu))).cast(dtypes.uint32),
    "mull.u": lambda: (au.cast(dtypes.uint32) & _u(0xffff)) * (bu.cast(dtypes.uint32) & _u(0xffff)),
    "clz.b": lambda: _clz(au, bits), "clz.s": lambda: _clz(au ^ (as_ < _u(0, st)).where(mask_all, _u(0, ut)), bits),
    "bfrev.b": lambda: _bitop_tree(au, bits, True), "cbits.b": lambda: _bitop_tree(au, bits, False),
    "getbit.b": lambda: (au >> sh) & _u(1, ut),
  }
  if op not in iops: raise NotImplementedError(f"ir3: no UOp model for cat2 {op}")
  return _as_bits(iops[op](), dst_h)

def _eval_cat3(op:str, full:bool, dst_h:bool, negs:tuple[bool, bool, bool], sat:bool, s0:UOp, s1:UOp, s2:UOp) -> UOp:
  if op in _CAT3_ALT:
    bits, ut = (16, dtypes.uint16) if not full else (32, dtypes.uint32)
    mask_all, sh_m = _u((1 << bits) - 1, ut), _u(bits - 1, ut)
    a, b, c = ((s.cast(ut) ^ mask_all) if n else s.cast(ut) for s, n in zip((s0, s1, s2), negs))
    alt = {"shrm": lambda: (b >> (a & sh_m)) & c, "shlm": lambda: (b << (a & sh_m)) & c,
           "shrg": lambda: (b >> (a & sh_m)) | c, "shlg": lambda: (b << (a & sh_m)) | c, "andg": lambda: (b & a) | c}
    return _as_bits(alt[op](), dst_h)
  is_h = op.endswith("16") and not op.startswith("madsh.")
  if ".f" in op:
    ft = dtypes.half if is_h else dtypes.float32
    a, b, c = (_bits_as(_fmod(s, is_h, n, False), ft) for s, n in zip((s0, s1, s2), negs))
    res = (a * b + c) if op.startswith("mad.") else (b >= UOp.const(0.0, ft)).where(a, c)
    return _as_bits(_sat(res.cast(dtypes.half if dst_h else dtypes.float32) if dst_h != is_h else res, sat), dst_h)
  ut, st = (dtypes.uint16, dtypes.int16) if is_h else (dtypes.uint32, dtypes.int32)
  u0, u1, u2 = s0.cast(dtypes.uint32), s1.cast(dtypes.uint32), s2.cast(dtypes.uint32)
  ops = {
    "sel.b": lambda: s1.cast(ut).ne(_u(0, ut)).where(s0.cast(ut), s2.cast(ut)),
    "sel.s": lambda: (s1.cast(st) >= _u(0, st)).where(s0.cast(st), s2.cast(st)),
    "sad.s": lambda: ((d := s0.cast(st) - s1.cast(st)) < _u(0, st)).where(_u(0, st) - d, d) + s2.cast(st),
    "mad.u16": lambda: (u0 & _u(0xffff)) * (u1 & _u(0xffff)) + u2,
    "mad.s16": lambda: s0.cast(dtypes.int16).cast(dtypes.int32) * s1.cast(dtypes.int16).cast(dtypes.int32) + s2.cast(dtypes.int32),
    "madsh.m16": lambda: (((u0 & _u(0xffff)) * ((u1 >> _u(16)) & _u(0xffff))) << _u(16)) + u2,
    "madsh.u16": lambda: (((u0 >> _u(16)) & _u(0xffff)) * ((u1 >> _u(16)) & _u(0xffff))) + u2,
    "mad.u24": lambda: (u0 & _u(0xffffff)) * (u1 & _u(0xffffff)) + u2,
    "mad.s24": lambda: (_sext24(u0) * _sext24(u1)).cast(dtypes.uint32) + u2,
  }
  if (fn := ops.get(op) or ops.get(op[:5])) is None: raise NotImplementedError(f"ir3: no UOp model for cat3 {op}")
  return _as_bits(fn(), dst_h)

# ***** Register File, Memory, and Single-Pass Canonical-Mask Instruction Lifting *****

# RF uint16 layout: 0..383 full GPRs r0..r47 (also hr0..hr191 if mergedregs), 384..575 hr0..hr47, 576..583 r48.xyzw, 584..587 p0.xyzw
RF_U16_PER_THREAD, CONST_DWORDS, TEX_DESC_DWORDS = 592, 2048, 16
SUPPORTED_TEX_FMTS = (mesa.FMT6_32_32_32_32_FLOAT, mesa.FMT6_16_16_16_16_FLOAT)

RF = UOp.param(0, dtypes.uint16, (RF_U16_PER_THREAD,), name="rf", addrspace=AddrSpace.REG)
CONSTS = UOp.param(1, dtypes.uint32, (CONST_DWORDS,), name="consts", addrspace=AddrSpace.GLOBAL)
LDS = UOp.param(3, dtypes.uint32, (16384,), name="lds", addrspace=AddrSpace.REG)
PVT = UOp.param(4, dtypes.uint32, (16384,), name="pvt", addrspace=AddrSpace.REG)
TEX_DESC = UOp.param(5, dtypes.uint32, (256 * TEX_DESC_DWORDS,), name="tex_desc", addrspace=AddrSpace.GLOBAL)
IBO_DESC = UOp.param(6, dtypes.uint32, (64 * TEX_DESC_DWORDS,), name="ibo_desc", addrspace=AddrSpace.GLOBAL)
LDS_DW, PVT_DW = (UOp.param(7 + i, dtypes.int, name=n, addrspace=AddrSpace.ALU) for i, n in enumerate(("lds_dw", "pvt_dw")))

def _is_pred(reg:int) -> bool: return 0xf8 <= reg <= 0xfb
def _stride(is_half:bool, is_pred:bool = False) -> int: return 1 if (is_half or is_pred) else 2

def _slot(reg:int, is_half:bool, mergedregs:bool) -> int:
  if _is_pred(reg): return 584 + (reg - 0xf8)
  if not is_half and 0xc0 <= reg <= 0xc3: return 576 + (reg - 0xc0) * 2
  if not (0 <= reg < 192): raise ValueError(f"ir3: reg out of bounds: {reg:#x}")
  return (reg if mergedregs else 384 + reg) if is_half else reg * 2

def _reg_slot(reg:int, is_half:bool, mergedregs:bool, count:int = 1) -> int:
  if _is_pred(reg) and count > 1: raise ValueError(f"ir3: vector access on predicate {reg:#x}")
  base, step = _slot(reg, is_half, mergedregs), _stride(is_half)
  if any(_slot(reg + k, is_half, mergedregs) != base + k * step for k in range(1, count)):
    raise ValueError(f"ir3: non-contiguous reg range {reg:#x} len={count}")
  return base

def _rf_read(rf:UOp, base:UOp, is_half:bool, is_pred:bool = False, k:int = 0) -> UOp:
  slot = base + _c(k * _stride(is_half, is_pred)) if k else base
  lo = rf.index(slot).load()
  if is_half: return lo
  return lo.cast(dtypes.uint32) if is_pred else (lo.cast(dtypes.uint32) | (rf.index(slot + _c(1)).load().cast(dtypes.uint32) << _u(16)))

def _rf_write(rf:UOp, base:UOp, val:UOp, is_half:bool, is_pred:bool = False, k:int = 0) -> tuple[UOp, list[UOp]]:
  slot = base + _c(k * _stride(is_half, is_pred)) if k else base
  if is_half or is_pred:
    st = rf.index(slot).store((val.cast(dtypes.uint32) & _u(1) if is_pred else val).cast(dtypes.uint16))
    return rf.after(st), [st]
  v32 = val.cast(dtypes.uint32)
  st0 = rf.index(slot).store((v32 & _u(0xffff)).cast(dtypes.uint16))
  st1 = rf.after(st0).index(slot + _c(1)).store(((v32 >> _u(16)) & _u(0xffff)).cast(dtypes.uint16))
  return rf.after(st1), [st0, st1]

def _const_read(idx:UOp, is_half:bool, is_float:bool, lane:int = 0) -> UOp:
  cv = CONSTS.index(((idx + _c(lane)) if lane else idx) & _c(0x7ff)).load()
  return cv if not is_half else (_f32_to_h16(cv) if is_float else (cv & _u(0xffff))).cast(dtypes.uint16)

class _Ctx(InstCtx):
  """Tracks dynamic operand bit ranges extracted from instruction words so one compiled LLVM body is shared across register/offset variations."""
  def __init__(self, ins:IR3Inst, mergedregs:bool):
    super().__init__()
    self.ins, self.mergedregs = ins, mergedregs
    for f in ("ss", "sy", "jp", "ul", "ei"):
      if (fld := ins._fields.get(f)) is not None: self.dyn_mask |= ((1 << (fld[1] - fld[0] + 1)) - 1) << fld[0]

  def bits(self, lo:int, hi:int, signed:bool = False) -> UOp: return self.extract_bits(lo, hi, signed).cast(dtypes.int)

  def field(self, name:str) -> UOp:
    lo, hi, signed, _ = self.ins._fields[name]
    return self.bits(lo, hi, signed)

  def reg(self, name:str, is_half:bool, count:int = 1, lo_override:int|None = None) -> tuple[UOp, bool]:
    lo = self.ins._fields[name][0] if lo_override is None else lo_override
    reg = (self.ins._raw >> lo) & 0xff
    static = _reg_slot(reg, is_half, self.mergedregs, count)
    # Keep bit 7 static in canonical mask so dynamic slots are guaranteed 0..127 (valid, contiguous, non-pred, non-r48).
    if reg < 128 and count <= 4:
      r = self.bits(lo, lo + 6)
      return ((r if self.mergedregs else r + _c(384)) if is_half else (r * _c(2))), False
    return _c(static), _is_pred(reg)

  def multisrc(self, name:str, is_half:bool, is_float:bool, count:int) -> tuple[Any, tuple[bool, bool]]:
    lo = self.ins._fields[name][0]
    raw16 = (self.ins._raw >> lo) & 0xffff
    neg, ab, k = bool((raw16 >> 14) & 1), bool((raw16 >> 15) & 1), (raw16 >> 11) & 7
    if k == 0:
      slot, is_pred = self.reg(name, is_half, count, lo)
      return (lambda rf, lane: _rf_read(rf, slot, is_half, is_pred, lane)), (neg, ab)
    if k == 2:
      idx = self.bits(lo, lo + 10)
      return (lambda rf, lane: _const_read(idx, is_half, is_float, lane)), (neg, ab)
    if k in (4, 5):
      if is_float:
        raw12 = raw16 & 0xfff
        if raw12 & 0x800:
          if (fi := raw12 & 0xf) >= len(FLOAT_IMMS): raise NotImplementedError(f"ir3: unknown #flut index {fi}")
          fv = FLOAT_IMMS[fi]
        else: fv = float(_sext(raw12 & 0x7ff, 11))
        imm = _u(struct.unpack("<H", struct.pack("<e", fv))[0], dtypes.uint16) if is_half else _u(struct.unpack("<I", struct.pack("<f", fv))[0])
      else: imm = self.bits(lo, lo + 10, signed=True).cast(dtypes.uint16 if is_half else dtypes.uint32)
      return (lambda rf, lane: imm), (neg, ab)
    raise NotImplementedError(f"ir3: unsupported #multisrc mode k={k:#x} raw={raw16:#x}")

  def cat3src(self, name:str, is_half:bool, is_float:bool, is_alt:bool, count:int) -> Any:
    lo = self.ins._fields[name][0]
    raw13 = (self.ins._raw >> lo) & 0x1fff
    if (raw13 >> 12) & 1:
      if is_alt:
        imm = self.bits(lo, lo + 10, signed=True).cast(dtypes.uint16 if is_half else dtypes.uint32)
        return lambda rf, lane: imm
      idx = self.bits(lo, lo + 10)
      return lambda rf, lane: _const_read(idx, is_half, is_float, lane)
    if (raw13 >> 11) & 1: raise NotImplementedError(f"ir3: relative #cat3-src not supported raw={raw13:#x}")
    slot, is_pred = self.reg(name, is_half, count, lo)
    return lambda rf, lane: _rf_read(rf, slot, is_half, is_pred, lane)

def _img_pix(desc:UOp, base_dw:UOp, cx:UOp, cy:UOp) -> tuple[UOp, UOp, UOp]:
  w0, w1, w2, w4, w5 = (desc.index(base_dw + _c(i)).load() for i in (0, 1, 2, 4, 5))
  fmt = (w0 & _u(mesa.A6XX_TEX_CONST_0_FMT__MASK)) >> _u(mesa.A6XX_TEX_CONST_0_FMT__SHIFT)
  is_f32, is_f16 = fmt.eq(_u(mesa.FMT6_32_32_32_32_FLOAT)), fmt.eq(_u(mesa.FMT6_16_16_16_16_FLOAT))
  w = ((w1 & _u(mesa.A6XX_TEX_CONST_1_WIDTH__MASK)) >> _u(mesa.A6XX_TEX_CONST_1_WIDTH__SHIFT)).cast(dtypes.int)
  h = ((w1 & _u(mesa.A6XX_TEX_CONST_1_HEIGHT__MASK)) >> _u(mesa.A6XX_TEX_CONST_1_HEIGHT__SHIFT)).cast(dtypes.int)
  pitch = ((w2 & _u(mesa.A6XX_TEX_CONST_2_PITCH__MASK)) >> _u(mesa.A6XX_TEX_CONST_2_PITCH__SHIFT)).cast(dtypes.uint64)
  base_ptr = w4.cast(dtypes.uint64) | (w5.cast(dtypes.uint64) << _u64(32))
  in_bounds = (cx >= _c(0)) & (cx < w) & (cy >= _c(0)) & (cy < h) & (is_f32 | is_f16)
  pix_b = base_ptr + cy.cast(dtypes.uint64) * pitch + cx.cast(dtypes.uint64) * is_f32.where(_u64(16), _u64(8))
  return UOp.range(in_bounds.cast(dtypes.int), 0, dtype=dtypes.int), pix_b >> _u64(2), is_f32

def _lower_inst(ins:IR3Inst, mergedregs:bool) -> tuple[UOp|None, UOp|None, int, int]:
  op, ctx, cur_rf, cur_mem, effs = ins.op_name, _Ctx(ins, mergedregs), RF, [VMEM, LDS, PVT], []
  def write_rep(dst:UOp, dst_h:bool, dp:bool, rpt:int, fn:Any) -> None:
    nonlocal cur_rf
    for k in range(rpt + 1):
      cur_rf, es = _rf_write(cur_rf, dst, fn(cur_rf, k), dst_h, dp, k)
      effs.extend(es)

  if op in ("mov-gpr", "mov-const", "mov-immed"):
    if ins.dst_rel: raise NotImplementedError("ir3 emu: relative dst on mov not supported")
    st, dt, rpt, r0 = ins.src_type, ins.dst_type, ins.repeat, bool(ins.src_r)
    dst, dp = ctx.reg("dst", dt.is_half, rpt + 1)
    if op == "mov-gpr":
      s0, sp = ctx.reg("src", st.is_half, (rpt + 1) if r0 else 1)
      write_rep(dst, dt.is_half, dp, rpt, lambda rf, k: _eval_mov(st, dt, _rf_read(rf, s0, st.is_half, sp, k if r0 else 0)))
    elif op == "mov-const":
      idx = ctx.field("src")
      write_rep(dst, dt.is_half, dp, rpt, lambda rf, k: _eval_mov(st, dt, _const_read(idx, st.is_half, st.is_float, k if r0 else 0)))
    else:
      imm = ctx.field("src").cast(dtypes.uint16 if st.is_half else dtypes.uint32)
      write_rep(dst, dt.is_half, dp, rpt, lambda rf, k: _eval_mov(st, dt, imm))
  elif op == "swz":
    st, dt = ins.src_type, ins.dst_type
    (d0, d0p), (d1, d1p), (s0, s0p), (s1, s1p) = (ctx.reg("dst0", dt.is_half), ctx.reg("dst1", dt.is_half),
                                                  ctx.reg("src0", st.is_half), ctx.reg("src1", st.is_half))
    v0, v1 = _eval_mov(st, dt, _rf_read(cur_rf, s0, st.is_half, s0p)), _eval_mov(st, dt, _rf_read(cur_rf, s1, st.is_half, s1p))
    cur_rf, es0 = _rf_write(cur_rf, d0, v0, dt.is_half, d0p)
    cur_rf, es1 = _rf_write(cur_rf, d1, v1, dt.is_half, d1p)
    effs.extend(es0 + es1)
  elif ins.cat == 2:
    is_f, is_u, full, rpt = op.endswith(".f"), op in _CAT2_UNARY, bool(ins.full), ins.repeat
    dst_h, r0, r1 = (not full) ^ bool(ins.dst_conv), bool(rpt and ins.src1_r), bool(rpt and ins.src2_r)
    dst, dp = ctx.reg("dst", _is_pred(ins.dst) or dst_h, rpt + 1)
    s0_fn, m0 = ctx.multisrc("src1", not full, is_f, (rpt + 1) if r0 else 1)
    z1 = _u(0, dtypes.uint16 if not full else dtypes.uint32)
    s1_fn, m1 = ((lambda rf, l: z1), (False, False)) if is_u else ctx.multisrc("src2", not full, is_f, (rpt + 1) if r1 else 1)
    cond, sat = (ins.cond if "cond" in ins._fields else IR3Cond.LT), bool(ins.sat)
    write_rep(dst, dst_h, dp, rpt, lambda rf, k: _eval_cat2(op, full, dst_h, m0, m1, cond, sat, s0_fn(rf, k if r0 else 0), s1_fn(rf, k if r1 else 0)))
  elif ins.cat == 3:
    is_alt = op in _CAT3_ALT
    full = bool(ins.full) if is_alt else not (op.endswith("16") and not op.startswith("madsh."))
    src_h, is_f, rpt = not full, ".f" in op, ins.repeat
    dst_h, r0, r1, r2 = src_h ^ bool(ins.dst_conv), bool(rpt and ins.src1_r), bool(rpt and ins.src2_r), bool(rpt and ins.src3_r)
    dst, dp = ctx.reg("dst", dst_h, rpt + 1)
    s0_fn = ctx.cat3src("src1", src_h, is_f, is_alt, (rpt + 1) if r0 else 1)
    s1, s1p = ctx.reg("src2", src_h, (rpt + 1) if r1 else 1)
    s2_fn = ctx.cat3src("src3", src_h, is_f, is_alt, (rpt + 1) if r2 else 1)
    negs, sat = (bool(ins.src1_neg), bool(ins.src2_neg), bool(ins.src3_neg)), (False if is_alt else bool(ins.sat))
    write_rep(dst, dst_h, dp, rpt, lambda rf, k: _eval_cat3(
      op, full, dst_h, negs, sat, s0_fn(rf, k if r0 else 0), _rf_read(rf, s1, src_h, s1p, k if r1 else 0), s2_fn(rf, k if r2 else 0)))
  elif ins.cat == 4 and op in _CAT4_FN:
    full, rpt = bool(ins.full), ins.repeat
    dst_h, r0, sat = (not full) ^ bool(ins.dst_conv), bool(rpt and ins.src_r), bool(ins.sat)
    dst, dp = ctx.reg("dst", dst_h, rpt + 1)
    s0_fn, (s0n, s0a) = ctx.multisrc("src", not full, True, (rpt + 1) if r0 else 1)
    def eval4(rf:UOp, k:int) -> UOp:
      af = _bits_as(_fmod(s0_fn(rf, k if r0 else 0), not full, s0n, s0a), dtypes.half if not full else dtypes.float32)
      rf_v = _CAT4_FN[op](af.cast(dtypes.float32) if not full else af)
      return _as_bits(_sat(rf_v.cast(dtypes.half) if dst_h else rf_v, sat), dst_h)
    write_rep(dst, dst_h, dp, rpt, eval4)
  elif op == "isam":
    if ins.type not in (IR3Type.F16, IR3Type.F32) or ins.s2en_bindless or ins._3d: raise NotImplementedError(f"ir3 emu: unsupported isam {ins!r}")
    is_f16, is_2d, chs = ins.type is IR3Type.F16, bool(ins._1d), [ch for ch in range(4) if ins.wrmask & (1 << ch)]
    dst, _ = ctx.reg("dst", is_f16, max(1, len(chs)))
    src1, _ = ctx.reg("src1", False, 2 if is_2d else 1)
    cx, cy = _rf_read(cur_rf, src1, False).cast(dtypes.int), (_rf_read(cur_rf, src1, False, k=1).cast(dtypes.int) if is_2d else _c(0))
    ib_r, pix_dw, is_f32 = _img_pix(TEX_DESC, ctx.field("tex") * _c(TEX_DESC_DWORDS), cx, cy)
    write_rep(dst, is_f16, False, len(chs) - 1, lambda rf, k: _u(0))
    v_loc, rf_loc, ld_es = VMEM.after(ib_r), cur_rf.after(ib_r), []
    for dk, ch in enumerate(chs):
      dw = v_loc.index((pix_dw + is_f32.where(_u64(ch), _u64(ch // 2))).cast(dtypes.int64)).load()
      h16 = (dw >> _u((ch & 1) * 16)) & _u(0xffff)
      rf_loc, es = _rf_write(rf_loc, dst, is_f32.where(_f32_to_h16(dw), h16) if is_f16 else is_f32.where(dw, _h16_to_f32(h16)), is_f16, False, dk)
      ld_es.extend(es)
    effs.append(UOp.group(*ld_es).end(ib_r))
  elif op in _LD_SPACE or op in _ST_SPACE:
    is_ld, space, typ, cnt = op in _LD_SPACE, (_LD_SPACE if op in _LD_SPACE else _ST_SPACE)[op], ins.type, ins.size
    esz = 1 if typ in (IR3Type.U8, IR3Type.U8_32) else (2 if typ.is_half else 4)
    areg, _ = ctx.reg("src1" if op in ("ldg", "stg") else ("src" if is_ld else "dst"), False, 2 if space == MEM_GLOBAL else 1)
    vreg, vpred = ctx.reg("dst" if is_ld else ("src3" if op == "stg" else "src"), typ.is_half, max(1, cnt))
    off = ctx.field("off") if is_ld else ((ctx.field("off_hi") << _c(8)) | ctx.field("off_lo"))
    if space == MEM_GLOBAL:
      base = _rf_read(cur_rf, areg, False).cast(dtypes.uint64) | (_rf_read(cur_rf, areg, False, k=1).cast(dtypes.uint64) << _u64(32))
      addr = base + off.cast(dtypes.int64).cast(dtypes.uint64)
    else: addr = (_rf_read(cur_rf, areg, False).cast(dtypes.int) + off).cast(dtypes.uint32)
    for k in range(cnt):
      a = addr + (_u64(k * esz) if space == MEM_GLOBAL else _u(k * esz))
      if space == MEM_GLOBAL: idx, sh, valid = (a >> _u64(2)).cast(dtypes.int64), (a & _u64(3)).cast(dtypes.uint32) << _u(3), None
      else:
        ai = a.cast(dtypes.int)
        valid = (ai >= _c(0)) & ((ai >> _c(2)) < (LDS_DW if space == MEM_LOCAL else PVT_DW))
        idx, sh = (ai >> _c(2)).valid(valid), (ai & _c(3)).cast(dtypes.uint32) << _u(3)
      if is_ld:
        dw = cur_mem[space].index(idx).load() if valid is None else valid.where(cur_mem[space].index(idx).load(), _u(0))
        cur_rf, es = _rf_write(cur_rf, vreg, dw if esz == 4 else ((dw >> sh) & _u((1 << (8 * esz)) - 1)), typ.is_half, vpred, k)
      else:
        v32 = _rf_read(cur_rf, vreg, typ.is_half, vpred, k).cast(dtypes.uint32)
        if esz < 4:
          mask = _u((1 << (8 * esz)) - 1) << sh
          old = cur_mem[space].index(idx).load() if valid is None else valid.where(cur_mem[space].index(idx).load(), _u(0))
          v32 = (old & (mask ^ _u(0xffffffff))) | ((v32 << sh) & mask)
        st = cur_mem[space].index(idx).store(v32)
        cur_mem[space], es = cur_mem[space].after(st), [st]
      effs.extend(es)
  elif op == "stib.b":
    if not (ins.typed == 1 and ins.d_minus_one == 1 and ins.type_size_minus_one == 3 and ins.mode == 0 and ins.bindless == 0
            and ins.type in (IR3Type.F16, IR3Type.F32)): raise NotImplementedError(f"ir3 emu: unsupported stib.b {ins!r}")
    if ins.ssbo >= 64: raise ValueError(f"ir3 emu: stib.b ssbo {ins.ssbo} out of range [0, 64)")
    is_f16 = ins.type is IR3Type.F16
    s1, _ = ctx.reg("src1", is_f16, 4)
    s2, _ = ctx.reg("src2", False, 2)
    ssbo_lo = ins._fields["ssbo"][0]
    ib_r, pix_dw, is_f32 = _img_pix(IBO_DESC, ctx.bits(ssbo_lo, ssbo_lo + 5) * _c(TEX_DESC_DWORDS),
                                    _rf_read(cur_rf, s2, False).cast(dtypes.int), _rf_read(cur_rf, s2, False, k=1).cast(dtypes.int))
    ch_vals = [((_h16_to_f32(r), r & _u(0xffff)) if is_f16 else (r, _f32_to_h16(r) & _u(0xffff)))
               for k in range(4) for r in (_rf_read(cur_rf, s1, is_f16, k=k).cast(dtypes.uint32),)]
    dws = [is_f32.where(ch_vals[0][0], ch_vals[0][1] | (ch_vals[1][1] << _u(16))),
           is_f32.where(ch_vals[1][0], ch_vals[2][1] | (ch_vals[3][1] << _u(16))), ch_vals[2][0], ch_vals[3][0]]
    v_loc, st_es = VMEM.after(ib_r), []
    for k in range(4):
      idx = (pix_dw + _u64(k)).cast(dtypes.int64)
      st = v_loc.index(idx if k < 2 else idx.valid(is_f32)).store(dws[k])
      st_es.append(st)
      v_loc = v_loc.after(st)
    effs.append(UOp.group(*st_es).end(ib_r))
  else: raise NotImplementedError(f"ir3 emu: unhandled instruction {ins!r}")

  cbase, cmask = ctx.canonical_mask(ins.to_bytes())
  nm = f"ir3_{op.replace('.', '_').replace('-', '_')}_{hashlib.md5(f'{cbase:x}_{cmask:x}_{mergedregs}'.encode()).hexdigest()[:10]}"
  return lower_body(UOp.sink(*effs, arg=KernelInfo(nm))), None, cbase, cmask

_INST_CACHE:InstCache = {}

def instruction_call(ins:IR3Inst, mergedregs:bool = False) -> tuple[UOp|None, UOp|None]:
  """Lower an IR3Inst to CALL(NATIVE(ins, body_sink), *args) and optional branch condition."""
  op = ins.op_name
  if op in ("nop", "fence", "bar", "end", "jump"): return None, None
  if op in _PRED_OPS: return None, (_rf_read(RF, _c(_slot(0xf8, True, mergedregs)), True).eq(_u(0, dtypes.uint16)) if op == "predt" else None)
  if op in _BRANCH_OPS:
    if op not in ("br", "brao", "braa"): raise NotImplementedError(f"ir3 emu: wave-uniform branch {op!r} not supported")
    def pred(comp:int, inv:int) -> UOp:
      p = _rf_read(RF, _c(_slot(0xf8 + comp, True, mergedregs)), True).ne(_u(0, dtypes.uint16))
      return p.logical_not() if inv else p
    c0 = pred(ins.comp1, ins.inv1)
    return None, (c0 if op == "br" else ((c0 | pred(ins.comp2, ins.inv2)) if op == "brao" else (c0 & pred(ins.comp2, ins.inv2))))
  return cached_inst_call(_INST_CACHE, (op, mergedregs), ins, ins.to_bytes(), lambda: _lower_inst(ins, mergedregs), max_entries=128)

# ***** CFG Construction, Lifting, and Execution *****

def _decode_and_cfg(raw_code:bytes) -> tuple[dict[int, IR3Inst], dict[int, list[int]], dict[int, dict[int, int]]]:
  n_words = len(raw_code) // 8
  if n_words == 0: raise ValueError("ir3: empty shader code")
  insts:dict[int, IR3Inst] = {}
  work = [0]
  while work:
    pc = work.pop()
    if pc in insts: continue
    if not (0 <= pc < n_words): raise ValueError(f"ir3: pc {pc} out of bounds [0, {n_words})")
    ins = insts[pc] = decode_inst(raw_code[pc * 8:pc * 8 + 8])
    if ins.op_name == "end": continue
    tgts = ([pc + ins.immed] if ins.op_name == "jump"
            else ([pc + ins.immed, pc + 1] if ins.op_name in _BRANCH_OPS else ([pc + 1] if pc + 1 < n_words else [])))
    for tgt in tgts:
      if not (0 <= tgt < n_words): raise ValueError(f"ir3: branch target {tgt} from pc={pc} out of bounds [0, {n_words})")
      work.append(tgt)

  stack:list[tuple[int, int|None]] = []
  ptgt:dict[int, int] = {}
  for pc in sorted(insts):
    if (op := insts[pc].op_name) == "predt": stack.append((pc, None))
    elif op == "predf":
      if not stack or stack[-1][1] is not None: raise ValueError(f"ir3: unmatched predf at pc={pc}")
      stack.append((stack.pop()[0], pc))
    elif op == "prede":
      if not stack: raise ValueError(f"ir3: unmatched prede at pc={pc}")
      t_pc, f_pc = stack.pop()
      if f_pc is not None: ptgt[t_pc], ptgt[f_pc] = f_pc + 1, pc
      else: ptgt[t_pc] = pc
  if stack: raise ValueError(f"ir3: unclosed predt at pc={stack[-1][0]}")

  starts = {0} | {pc + ins.immed for pc, ins in insts.items() if ins.op_name == "jump" or ins.op_name in _BRANCH_OPS} | set(ptgt.values())
  starts |= {pc for pc, ins in insts.items() if ins.op_name == "prede"}
  starts |= {pc + 1 for pc, ins in insts.items() if ins.op_name in _CFG_END_OPS and (pc + 1) in insts}
  blocks:dict[int, list[int]] = {}
  paths:dict[int, dict[int, int]] = {}
  for s in sorted(starts):
    pcs, cur = [s], s
    while (cur + 1) in insts and insts[cur].op_name not in _CFG_END_OPS and (cur + 1) not in starts:
      cur += 1
      pcs.append(cur)
    blocks[s], (lpc, lop) = pcs, (pcs[-1], insts[pcs[-1]].op_name)
    if lop == "end": paths[s] = {}
    elif lop == "jump": paths[s] = {lpc + insts[lpc].immed: UNCOND}
    elif lop in _BRANCH_OPS or lop == "predt":
      tgt, ft = (ptgt[lpc] if lop == "predt" else lpc + insts[lpc].immed), lpc + 1
      paths[s] = {tgt: UNCOND} if tgt == ft else {tgt: COND_TAKEN, ft: COND_NOT_TAKEN}
    elif lop == "predf": paths[s] = {ptgt[lpc]: UNCOND}
    else: paths[s] = {lpc + 1: UNCOND} if (lpc + 1) in insts else {}
  return insts, blocks, paths

def lift(raw_code:bytes, dispatch:tuple[int, int, int, int, int, int, int, int, bool, int, int], name:str = "ir3_emu") -> UOp:
  insts, blocks, paths = _decode_and_cfg(raw_code)
  gx, gy, gz, lx, ly, lz, shmem_sz, pvt_sz, mergedregs, wgid_reg, lid_reg = dispatch
  n_threads, pvt_dw, lds_dw = lx * ly * lz, max(4, round_up(pvt_sz, 16) // 4), max(4, round_up(shmem_sz, 16) // 4)
  wg, tid = UOp.range(gx * gy * gz, 0, dtype=dtypes.int), UOp.range(n_threads, 1, dtype=dtypes.int)
  rf_all = UOp.alloc((n_threads * RF_U16_PER_THREAD,), dtypes.uint16, 0, AddrSpace.REG)
  lds_all = UOp.alloc((lds_dw,), dtypes.uint32, 3, AddrSpace.REG)
  pvt_all = UOp.alloc((n_threads * pvt_dw,), dtypes.uint32, 4, AddrSpace.REG)
  buffers = {RF: (rf_all, RF_U16_PER_THREAD), CONSTS: (CONSTS, 0), VMEM: (VMEM, 0), LDS: (lds_all, 0),
             PVT: (pvt_all, pvt_dw), TEX_DESC: (TEX_DESC, 0), IBO_DESC: (IBO_DESC, 0)}

  rfi, pvi = UOp.range(RF_U16_PER_THREAD, 2, dtype=dtypes.int), UOp.range(pvt_dw, 3, dtype=dtypes.int)
  z_rf = rf_all.after(wg).index(tid * _c(RF_U16_PER_THREAD) + rfi).store(_u(0, dtypes.uint16)).end(rfi)
  z_pvt = pvt_all.after(wg).index(tid * _c(pvt_dw) + pvi).store(_u(0)).end(pvi)
  cur_rf, init_effs = rf_all.after(z_rf).shrink(((tid * _c(RF_U16_PER_THREAD), (tid + _c(1)) * _c(RF_U16_PER_THREAD)),)), [z_rf, z_pvt]
  for reg, vals in ((lid_reg, (tid % _c(lx), (tid // _c(lx)) % _c(ly), tid // _c(lx * ly))),
                    (wgid_reg, (wg % _c(gx), (wg // _c(gx)) % _c(gy), wg // _c(gx * gy)))):
    if reg != 0xfc:
      for d, v in enumerate(vals):
        cur_rf, es = _rf_write(cur_rf, _c(_slot(reg + d, False, False)), v.cast(dtypes.uint32), False)
        init_effs.extend(es)
  return lift_cfg(blocks, paths, lambda pc: instruction_call(insts[pc], mergedregs), buffers, {LDS_DW: _c(lds_dw), PVT_DW: _c(pvt_dw)},
                  wg, tid, n_threads, UOp.group(*init_effs), VMEM, name, axes=itertools.count(4), block_name="emu_threads")

_DISPATCH_CACHE:dict[tuple, UOp] = {}

def _alloc_buf(size:int, addr:int = 0, copy_sz:int = 0, validate_n:int = 0) -> UOp:
  buf = Buffer("CPU", size).allocate()
  ctypes.memset(buf.host.addr, 0, size)
  if addr and copy_sz > 0:
    raw = bytes(to_mv(addr, copy_sz))
    for i in range(validate_n):
      w0, _, _, _, w4, w5 = struct.unpack_from("<6I", raw, i * 64)
      fmt = (w0 & mesa.A6XX_TEX_CONST_0_FMT__MASK) >> mesa.A6XX_TEX_CONST_0_FMT__SHIFT
      if (w0 | w4 | w5) and fmt not in SUPPORTED_TEX_FMTS: raise NotImplementedError(f"ir3 emu: unsupported texture format {fmt:#x}")
    buf.host.view(fmt="B")[:copy_sz] = raw
  return UOp.from_buffer(buf, dtypes.uint32)

def run_qcom_asm(code_addr:int, code_sz:int, gx:int, gy:int, gz:int, lx:int, ly:int, lz:int,
                 const_addr:int = 0, const_sz:int = 0, tex_addr:int = 0, n_tex:int = 0,
                 ibo_addr:int = 0, n_ibo:int = 0, shmem:int = 0, pvtmem:int = 0,
                 mergedregs:bool = False, wgid_reg:int = 0xc0, lid_reg:int = 0x00, name:str = "ir3_asm") -> None:
  if not (0 <= const_sz <= CONST_DWORDS * 4): raise ValueError(f"ir3 emu: const_sz {const_sz} out of range")
  if not (0 <= n_tex <= 256) or not (0 <= n_ibo <= 64): raise ValueError(f"ir3 emu: descriptor count out of range ({n_tex}, {n_ibo})")
  raw_code, dispatch = bytes(to_mv(code_addr, code_sz)), (gx, gy, gz, lx, ly, lz, shmem, pvtmem, mergedregs, wgid_reg, lid_reg)
  with emu_context():
    prg, _ = compile_program(_DISPATCH_CACHE, (raw_code, dispatch, name), lambda _: lift(raw_code, dispatch, name=name))
  run_program(prg, {"vmem": vmem_buf(), "consts": _alloc_buf(CONST_DWORDS * 4, const_addr, const_sz),
                    "tex_desc": _alloc_buf(256 * TEX_DESC_DWORDS * 4, tex_addr, n_tex * 64, n_tex),
                    "ibo_desc": _alloc_buf(64 * TEX_DESC_DWORDS * 4, ibo_addr, n_ibo * 64, n_ibo)})
